#!/bin/bash
# Generated by scripts/export-killercoda.ts for lab-m04-observe-reconciliation. Setup for the Killercoda VM: runs as root, builds the course's own lab environment.
# Every tool is pinned, with the versions and SHA-256 sums from the course's tools/pins.tsv.
set -uo pipefail
LOG=/tmp/shelf-setup.log
exec >"$LOG" 2>&1
start=$(date +%s)
export HOME=${HOME:-/root}
fail() { echo "FAILED: $1"; echo "$1" > /tmp/shelf-failed; echo "seconds: $(( $(date +%s) - start ))" > /tmp/shelf-setup-seconds; exit 1; }

install_tool() { # name version url sha256 strip bins
  local f="/tmp/download-$1" d b IFS=,
  curl -fsSL --retry 3 -o "$f" "$3" || fail "download $1"
  echo "$4  $f" | sha256sum -c - || fail "checksum $1"
  case "$3" in
    *.tar.gz|*.tar.xz)
      d="/opt/tools/$1-$2"; mkdir -p "$d"
      tar -xf "$f" -C "$d" --strip-components="$5" || fail "unpack $1"
      for b in $6; do ln -sf "$d/$b" "/usr/local/bin/$(basename "$b")"; done ;;
    *) install -m 0755 "$f" "/usr/local/bin/$6" ;;
  esac
}

install_tool kind 0.33.0 https://github.com/kubernetes-sigs/kind/releases/download/v0.33.0/kind-linux-amd64 aee6151561422756b764a4ae28e7f44cda5af5a9eead3cc9985112b1de8d8e0d 0 kind
install_tool kubectl 1.37.2 https://dl.k8s.io/release/v1.37.2/bin/linux/amd64/kubectl c04487523e7aa7d1493f7808174c899db93d7a9cf57531420cd76b9bd415f8f4 0 kubectl
install_tool go 1.27.4 https://go.dev/dl/go1.27.4.linux-amd64.tar.gz 7226736c2339719cda28fbf3a54d71aa63bcefe376e98cef00034268dab24840 1 bin/go,bin/gofmt
export PATH="/opt/tools/go-1.27.4/bin:$PATH" GOTOOLCHAIN=local GOFLAGS=-mod=readonly GOPATH=/tmp/go-path GOCACHE=/tmp/go-cache

docker version >/dev/null || fail "docker is not available"
# kind needs more inotify watches than the Ubuntu default (kind known issues).
sysctl -w fs.inotify.max_user_watches=524288 fs.inotify.max_user_instances=512 || true

# The course source, at the pinned commit.
mkdir -p /root/course && cd /root/course || fail "create /root/course"
git init -q . && git remote add origin https://github.com/berserkhmdvhb/k8s_training.git || fail "git init"
git fetch -q --depth 1 origin ed9aebcfb3c91d29b4e05b3b4c534850565aa68c || fail "git fetch ed9aebcfb3c91d29b4e05b3b4c534850565aa68c"
git checkout -q FETCH_HEAD || fail "git checkout"

# The shelf CLI.
mkdir -p /root/course/labs/bin
(cd /root/course/labs/cli && go build -o ../bin/shelf .) || fail "build the shelf CLI"
ln -sf /root/course/labs/bin/shelf /usr/local/bin/shelf

# The Shelf images, into the local registry that `shelf up` expects (localhost:5001).
docker buildx version >/dev/null || fail "docker buildx is not available"
bash apps/shelf/scripts/registry.sh up || fail "start the local registry"
bash apps/shelf/scripts/build-images.sh v1 || fail "build the Shelf images"

shelf up default || fail "shelf up default"
shelf setup lab-m04-observe-reconciliation || fail "shelf setup lab-m04-observe-reconciliation"
cat >> /root/.bashrc <<'EOF'
export KUBECONFIG=/root/.kube/config
cd /root/course
EOF

echo "seconds: $(( $(date +%s) - start ))" > /tmp/shelf-setup-seconds
touch /tmp/shelf-ready
echo "DONE"

